import type { MetadataRoute } from "next";
import { BRAND } from "@/lib/brand";

/** Web app manifest: name and icons from the central brand config (icons generated by assets/brand/make_brand_assets.py). */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: BRAND.name.en,
    short_name: "UNAVORA ANANT",
    description: `${BRAND.name.en} — ${BRAND.tagline}`,
    start_url: "/en",
    display: "browser",
    background_color: BRAND.colours.cream,
    theme_color: "#101d35",
    icons: [
      { src: BRAND.icons.pwa192, sizes: "192x192", type: "image/png" },
      { src: BRAND.icons.pwa512, sizes: "512x512", type: "image/png" },
    ],
  };
}
